CREATE OR REPLACE FUNCTION public.dic_preview_cached_verified(p_source_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=auth.uid(); ids uuid[]; coffee public.coffees;
begin
 if me is null or auth.role() is distinct from 'authenticated' or not private.is_member() then
  raise exception using errcode='42501',message='Admitted member required.';
 end if;
 if not exists(select 1 from auth.users u where u.id=me and u.email_confirmed_at is not null) then
  raise exception using errcode='42501',message='Email confirmation required.';
 end if;
 if p_source_url is null or length(p_source_url)>900 or
   p_source_url not like 'https://%' then return null; end if;
 select array_agg(distinct c.id) into ids
 from public.coffee_sources s join public.coffees c on c.id=s.coffee_id
 where s.source_url=p_source_url and s.source_kind='roaster_page'
   and c.verification_state='verified' and c.merged_into_id is null;
 if coalesce(array_length(ids,1),0)<>1 then return null; end if;
 select * into strict coffee from public.coffees where id=ids[1];
 return jsonb_build_object(
  'ok',true,'source','verified_catalog','cached',true,'source_url',p_source_url,
  'fields',jsonb_strip_nulls(jsonb_build_object(
   'name',coffee.name,'roaster',coffee.roaster,'release_label',coffee.release_label,
   'origin',coffee.origin,'process',coffee.process,'roast_level',coffee.roast_level,
   'variety',coffee.variety,'producer',coffee.producer,
   'elevation_m',coffee.elevation_m,'tasting_notes',coffee.tasting_notes,
   'summary',coffee.summary,'espresso_notes',coffee.espresso_notes)));
end $function$

CREATE OR REPLACE FUNCTION public.dic_preview_complete(p_ticket uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 me uuid:=auth.uid();
 rec private.dic_url_preview_attempts;
begin
 if me is null or auth.role() is distinct from 'authenticated' or not private.is_member() then
  return jsonb_build_object('charged',false,'reason','admitted_member_required');
 end if;
 if p_ticket is null then return jsonb_build_object('charged',false,'reason','invalid_ticket'); end if;
 if private.is_admin()
   and exists(select 1 from auth.users u where u.id=me and u.email_confirmed_at is not null) then
  return jsonb_build_object('charged',true,'unlimited',true);
 end if;
 select * into rec from private.dic_url_preview_attempts where owner_id=me for update;
 if not found or rec.preview_ticket is distinct from p_ticket or
   rec.preview_ticket_at is null or rec.preview_ticket_at<now()-interval '25 seconds' then
  return jsonb_build_object('charged',false,'reason','invalid_ticket');
 end if;
 if rec.attempts>=12 then return jsonb_build_object('charged',false,'reason','daily_preview_limit'); end if;
 update private.dic_url_preview_attempts
 set attempts=rec.attempts+1,preview_ticket=null,preview_ticket_at=null where owner_id=me;
 return jsonb_build_object('charged',true);
end $function$

CREATE OR REPLACE FUNCTION public.dic_preview_preflight(p_cached boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 me uuid:=auth.uid();
 rec private.dic_url_preview_attempts;
 clock timestamptz:=now();
 ticket uuid;
begin
 if me is null or auth.role() is distinct from 'authenticated' or not private.is_member() then
  return jsonb_build_object('allowed',false,'reason','admitted_member_required');
 end if;
 if not exists(select 1 from auth.users u where u.id=me and u.email_confirmed_at is not null) then
  return jsonb_build_object('allowed',false,'reason','verify_email');
 end if;
 if p_cached is null then
  return jsonb_build_object('allowed',false,'reason','invalid_cached_flag');
 end if;
 -- Admin ticket only acknowledges a read-only preview. No account cap,
 -- waiting, counter row mutation, or serialized ticket lock for admins.
 if private.is_admin() then
  if p_cached then
   return jsonb_build_object('allowed',true,'cached',true,'unlimited',true);
  end if;
  return jsonb_build_object('allowed',true,'ticket',gen_random_uuid(),'unlimited',true);
 end if;
 insert into private.dic_url_preview_attempts(owner_id,window_started_at,last_attempt_at,attempts)
 values(me,clock,clock-interval '1 minute',0) on conflict(owner_id) do nothing;
 select * into strict rec from private.dic_url_preview_attempts where owner_id=me for update;
 if rec.window_started_at<clock-interval '24 hours' then
  update private.dic_url_preview_attempts
    set window_started_at=clock,attempts=0,preview_ticket=null,preview_ticket_at=null
    where owner_id=me;
  rec.attempts:=0;
 end if;
 -- A cached public result consumes cooldown but never a daily retrieval claim.
 if not p_cached and rec.attempts>=12 then
  return jsonb_build_object('allowed',false,'reason','daily_preview_limit');
 end if;
 if rec.last_attempt_at>clock-interval '15 seconds' then
  return jsonb_build_object('allowed',false,'reason','preview_cooldown');
 end if;
 if p_cached then
  update private.dic_url_preview_attempts
    set last_attempt_at=clock,preview_ticket=null,preview_ticket_at=null where owner_id=me;
  return jsonb_build_object('allowed',true,'cached',true);
 end if;
 ticket:=gen_random_uuid();
 update private.dic_url_preview_attempts
  set last_attempt_at=clock,preview_ticket=ticket,preview_ticket_at=clock where owner_id=me;
 return jsonb_build_object('allowed',true,'ticket',ticket);
end $function$

CREATE OR REPLACE FUNCTION public.dic_source_check_target(submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.coffee_submissions; host text; cname text;
begin
 if coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
             nullif(current_setting('request.jwt.claim.role',true),'')) is distinct from 'service_role' then
  raise exception using errcode='42501',message='Trusted source worker required.';
 end if;
 select * into s from public.coffee_submissions
 where id=submission_id and status in ('pending','conflict');
 if not found then return null; end if;
 if not exists(select 1 from private.beta_members where owner_id=s.owner_id and enabled) then
  return null;
 end if;
 select proof->>'official_domain',proof->>'canonical_name'
 into host,cname
 from (select private.dic_verified_roaster_page_proof(s.proposed_data->>'roaster') as proof) p;
 if host is null or s.source_url is null then return null; end if;
 return jsonb_build_object('submission_id',s.id,'submission_revision',s.revision,'source_url',s.source_url,
  'official_host',host,'roaster',cname,'name',s.proposed_data->>'name',
  'release_label',s.proposed_data->>'release_label',
  'origin',s.proposed_data->>'origin','process',s.proposed_data->>'process','producer',s.proposed_data->>'producer');
end $function$

CREATE OR REPLACE FUNCTION public.dic_source_claim(submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; existing private.dic_source_attempts; total_24h integer;
begin
 if coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
             nullif(current_setting('request.jwt.claim.role',true),'')) is distinct from 'service_role' then
  raise exception using errcode='42501',message='Trusted worker required.';
 end if;
 select owner_id into actor from public.coffee_submissions
 where id=submission_id and status in ('pending','conflict');
 if actor is null then return jsonb_build_object('allowed',false,'reason','not_pending');end if;
 -- Share lock keeps admission stable for this atomic budget claim.
 perform 1 from private.beta_members where owner_id=actor and enabled for share;
 if not found then return jsonb_build_object('allowed',false,'reason','not_admitted');end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text,9470));
 select attempts.* into existing from private.dic_source_attempts as attempts
 where attempts.submission_id=dic_source_claim.submission_id for update;
 select coalesce(sum(attempts),0) into total_24h from private.dic_source_attempts
 where owner_id=actor and window_started_at>now()-interval '24 hours';
 if total_24h>=30 then return jsonb_build_object('allowed',false,'reason','account_budget');end if;
 if existing.submission_id is not null
  and existing.window_started_at>now()-interval '24 hours'
  and (existing.attempts>=6 or existing.started_at>now()-interval '15 minutes') then
  return jsonb_build_object('allowed',false,'reason','retry_later');
 end if;
 insert into private.dic_source_attempts(submission_id,owner_id,started_at,window_started_at,attempts)
 values(dic_source_claim.submission_id,actor,now(),now(),1)
 on conflict on constraint dic_source_attempts_pkey do update set
  started_at=now(),
  window_started_at=case when private.dic_source_attempts.window_started_at<=now()-interval '24 hours'
   then now() else private.dic_source_attempts.window_started_at end,
  attempts=case when private.dic_source_attempts.window_started_at<=now()-interval '24 hours'
   then 1 else private.dic_source_attempts.attempts+1 end;
 return jsonb_build_object('allowed',true);
end $function$
